65| \begin{tikzpicture}[font=\small]
66|   \draw (0,0) to[generic, l=二端元件, v=$u$, i=$i$] (3,0);
67|   \node[below] at (1.5,-1.0) {负载约定：$p_{\text{received}} = ui$};
68|   \begin{scope}[xshift=6cm]
69|   \draw (0,0) to[generic, l=二端元件, v<=$u$, i=$i$] (3,0);
70|   \node[below] at (1.5,-1.0) {电源约定：$p_{\text{delivered}} = ui$};
71|   \end{scope}
72| \end{tikzpicture}
